def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C'
    if n == 2:
        return 'D'

    my = [h[0] for h in history]
    opp = [h[1] for h in history]
    opp_c = opp.count('C')
    opp_d = n - opp_c
    last_me = my[-1]
    last_opp = opp[-1]

    total_my_D = 0
    opp_C_after_my_D = 0
    for i in range(1, n):
        if my[i-1] == 'D':
            total_my_D += 1
            if opp[i] == 'C':
                opp_C_after_my_D += 1

    p_opp_C_given_my_D = opp_C_after_my_D / total_my_D if total_my_D > 0 else 1.0

    if n >= 5 and opp_d > n * 0.7:
        return 'D'

    if n >= 99:
        return 'D'
    if n == 98:
        if last_opp == 'D' or opp_d > n * 0.5:
            return 'D'
        return 'C'
    if n >= 95:
        if opp_d > n * 0.5:
            return 'D'
        return 'C'

    if total_my_D >= 1 and p_opp_C_given_my_D > 0.7 and opp_c > n * 0.5:
        return 'D'

    if total_my_D >= 1 and p_opp_C_given_my_D < 0.3:
        if last_opp == 'D':
            if last_me == 'C':
                if opp_d > n * 0.5:
                    return 'D'
                return 'C' if rng.random() < 0.8 else 'D'
            else:
                if rng.random() < 0.3:
                    return 'C'
                return 'D'
        else:
            return 'C'

    if last_opp == 'D':
        if last_me == 'C':
            if opp_d > n * 0.5:
                return 'D'
            return 'C' if rng.random() < 0.8 else 'D'
        else:
            if rng.random() < 0.3:
                return 'C'
            return 'D'
    else:
        if last_me == 'D':
            return 'C'
        else:
            if opp_d == 0 and n > 20 and rng.random() < 0.1:
                return 'D'
            return 'C'
